		this.cache = options.cache || false;
		/** @type {Array<Promise<import('./imagefiledirectory.js').ImageFileDirectory> | undefined>} */
		this.ifdRequests = [];
		/** @type {Record<string, unknown>|null} */
		this.ghostValues = null;
