//#region src/tiffReader.ts
async function readTiffPixels(file) {
	console.log(`📂 Abrindo arquivo ${file.name}...`);
	const image = await (await fromArrayBuffer(await file.arrayBuffer())).getImage();
	const rasters = await image.readRasters();
	const width = image.getWidth();
	const height = image.getHeight();
	const origin = image.getOrigin();
	const resolution = image.getResolution();
	const geoKeys = image.getGeoKeys();
	let epsg = 3857;
	let isProjected = true;
	if (geoKeys) {
		if (geoKeys.ProjectedCSTypeGeoKey) {
			epsg = geoKeys.ProjectedCSTypeGeoKey;
			isProjected = true;
		} else if (geoKeys.GeographicTypeGeoKey) {
			epsg = geoKeys.GeographicTypeGeoKey;
			isProjected = false;
		}
	}
	console.log(`📍 Geografia Lida - EPSG:${epsg} | Origem:`, origin);
	return {
		rasters,
		width,
		height,
		origin: origin ? Array.from(origin) : [
			0,
			0,
			0
		],
		resolution: resolution ? Array.from(resolution) : [
			1,
			1,
			0
		],
		epsg,
		isProjected
	};
}
