//#region src/downscaling.ts
/**
* Aplica o algoritmo TsHARP (Regressão Linear) para fazer o downscaling da Temperatura.
* Cruzamos o detalhe do NDVI (1m) com a Temperatura (LST).
*/
function applyTsHARP(ndvi1m, lstBase) {
	const totalPixels = ndvi1m.length;
	const lstDownscaled = new Float32Array(totalPixels);
	console.log("📐 A iniciar o treino do modelo TsHARP (Regressão Linear)...");
	let sumNdvi = 0;
	let sumLst = 0;
	let validPixels = 0;
	for (let i = 0; i < totalPixels; i++) if (ndvi1m[i] > 0 && !isNaN(lstBase[i])) {
		sumNdvi += ndvi1m[i];
		sumLst += lstBase[i];
		validPixels++;
	}
	const meanNdvi = sumNdvi / validPixels;
	const meanLst = sumLst / validPixels;
	let numerador = 0;
	let denominador = 0;
	for (let i = 0; i < totalPixels; i++) if (ndvi1m[i] > 0 && !isNaN(lstBase[i])) {
		const diffNdvi = ndvi1m[i] - meanNdvi;
		const diffLst = lstBase[i] - meanLst;
		numerador += diffNdvi * diffLst;
		denominador += diffNdvi * diffNdvi;
	}
	const slope = denominador !== 0 ? numerador / denominador : 0;
	const intercept = meanLst - slope * meanNdvi;
	console.log(`📊 Equação TsHARP encontrada: Temperatura = (${slope.toFixed(2)} * NDVI) + ${intercept.toFixed(2)}`);
	for (let i = 0; i < totalPixels; i++) lstDownscaled[i] = slope * ndvi1m[i] + intercept;
	return {
		lstDownscaled,
		slope,
		intercept
	};
}
//#endregion
//#region src/colorMapper.ts
function renderLstToCanvas(lstData, width, height, canvas, palette = "ironbow", customColors = [
	"#000080",
	"#0000ff",
	"#00ff00",
	"#ffff00",
	"#ff0000"
]) {
	canvas.width = width;
	canvas.height = height;
	const ctx = canvas.getContext("2d");
	if (!ctx) return null;
	const imageData = ctx.createImageData(width, height);
	const data = imageData.data;
	let min = Infinity, max = -Infinity;
	let sum = 0, count = 0;
	for (let i = 0; i < lstData.length; i++) {
		const val = lstData[i];
		if (!isNaN(val) && isFinite(val)) {
			if (val < min) min = val;
			if (val > max) max = val;
			sum += val;
			count++;
		}
	}
	const range = max - min || 1;
	const mean = count > 0 ? sum / count : 0;
	let sumSqDiff = 0;
	for (let i = 0; i < lstData.length; i++) {
		const val = lstData[i];
		if (!isNaN(val) && isFinite(val)) sumSqDiff += Math.pow(val - mean, 2);
	}
	const stdDev = count > 0 ? Math.sqrt(sumSqDiff / count) : 1;
	const customRgb = customColors.map(hexToRgb);
	for (let i = 0; i < lstData.length; i++) {
		const val = lstData[i];
		const idx = i * 4;
		if (isNaN(val) || !isFinite(val)) {
			data[idx + 3] = 0;
			continue;
		}
		const color = getThermalColor(val, Math.min(Math.max((val - min) / range, 0), 1), palette, customRgb, mean, stdDev);
		data[idx] = color.r;
		data[idx + 1] = color.g;
		data[idx + 2] = color.b;
		data[idx + 3] = 255;
	}
	ctx.putImageData(imageData, 0, 0);
	return {
		min,
		max,
		mean,
		stdDev
	};
}
function hexToRgb(hex) {
	const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
	return r ? {
		r: parseInt(r[1], 16),
		g: parseInt(r[2], 16),
		b: parseInt(r[3], 16)
	} : {
		r: 0,
		g: 0,
		b: 0
	};
}
function getThermalColor(rawVal, v, palette, customRgb, mean, stdDev) {
	if (palette === "uhi") {
		if (rawVal < mean) return {
			r: 26,
			g: 150,
			b: 65
		};
		if (rawVal < mean + .5 * stdDev) return {
			r: 254,
			g: 224,
			b: 139
		};
		if (rawVal < mean + 1.5 * stdDev) return {
			r: 253,
			g: 141,
			b: 60
		};
		return {
			r: 215,
			g: 25,
			b: 28
		};
	}
	if (palette === "grayscale") {
		const cv = Math.round(v * 255);
		return {
			r: cv,
			g: cv,
			b: cv
		};
	}
	let stops = palette === "spectral" ? [
		{
			p: 0,
			r: 94,
			g: 79,
			b: 162
		},
		{
			p: .2,
			r: 50,
			g: 136,
			b: 189
		},
		{
			p: .4,
			r: 102,
			g: 194,
			b: 165
		},
		{
			p: .6,
			r: 253,
			g: 212,
			b: 134
		},
		{
			p: .8,
			r: 244,
			g: 109,
			b: 67
		},
		{
			p: 1,
			r: 158,
			g: 1,
			b: 66
		}
	] : palette === "jet" ? [
		{
			p: 0,
			r: 0,
			g: 0,
			b: 130
		},
		{
			p: .25,
			r: 0,
			g: 255,
			b: 255
		},
		{
			p: .5,
			r: 0,
			g: 255,
			b: 0
		},
		{
			p: .75,
			r: 255,
			g: 255,
			b: 0
		},
		{
			p: 1,
			r: 255,
			g: 0,
			b: 0
		}
	] : palette === "custom" ? customRgb.map((c, i) => ({
		p: i / (customRgb.length - 1),
		...c
	})) : [
		{
			p: 0,
			r: 0,
			g: 0,
			b: 130
		},
		{
			p: .25,
			r: 120,
			g: 0,
			b: 120
		},
		{
			p: .5,
			r: 204,
			g: 0,
			b: 0
		},
		{
			p: .75,
			r: 255,
			g: 204,
			b: 0
		},
		{
			p: 1,
			r: 255,
			g: 255,
			b: 255
		}
	];
	if (v <= 0) return stops[0];
	if (v >= 1) return stops[stops.length - 1];
	for (let i = 0; i < stops.length - 1; i++) if (v >= stops[i].p && v <= stops[i + 1].p) {
		const t = (v - stops[i].p) / (stops[i + 1].p - stops[i].p);
		return {
			r: Math.round(stops[i].r + t * (stops[i + 1].r - stops[i].r)),
			g: Math.round(stops[i].g + t * (stops[i + 1].g - stops[i].g)),
			b: Math.round(stops[i].b + t * (stops[i + 1].b - stops[i].b))
		};
	}
	return stops[0];
}
function renderRGBBasemapToCanvas(band1, band2, band3, width, height, canvas) {
	canvas.width = width;
	canvas.height = height;
	const ctx = canvas.getContext("2d");
	if (!ctx) return;
	const imageData = ctx.createImageData(width, height);
	const data = imageData.data;
	let min = Infinity, max = -Infinity;
	for (let i = 0; i < band1.length; i += 100) {
		if (band1[i] > 0 && band1[i] < min) min = band1[i];
		if (band1[i] > max) max = band1[i];
	}
	const range = max - min || 1;
	for (let i = 0; i < band1.length; i++) {
		const idx = i * 4;
		if (band1[i] <= 0 || isNaN(band1[i])) {
			data[idx + 3] = 0;
			continue;
		}
		data[idx] = Math.round(Math.min(Math.max((band1[i] - min) / range, 0), 1) * 255);
		data[idx + 1] = Math.round(Math.min(Math.max((band2[i] - min) / range, 0), 1) * 255);
		data[idx + 2] = Math.round(Math.min(Math.max((band3[i] - min) / range, 0), 1) * 255);
		data[idx + 3] = 255;
	}
	ctx.putImageData(imageData, 0, 0);
}
