/**
* 🚀 Exporta GeoTIFF usando um layout de memória estático à prova de falhas.
*/
async function downloadFloat32Tiff(data, width, height, filename, origin, resolution, epsg, isProjected) {
	try {
		const fileSize = 288 + data.length * 4;
		const buffer = new ArrayBuffer(fileSize);
		const view = new DataView(buffer);
		view.setUint16(0, 18761, false);
		view.setUint16(2, 42, true);
		view.setUint32(4, 8, true);
		view.setUint16(8, 14, true);
		let offset = 10;
		const addTag = (tag, type, count, val) => {
			view.setUint16(offset, tag, true);
			view.setUint16(offset + 2, type, true);
			view.setUint32(offset + 4, count, true);
			if (type === 3 && count === 1) {
				view.setUint16(offset + 8, val, true);
				view.setUint16(offset + 10, 0, true);
			} else view.setUint32(offset + 8, val, true);
			offset += 12;
		};
		addTag(256, 4, 1, width);
		addTag(257, 4, 1, height);
		addTag(258, 3, 1, 32);
		addTag(259, 3, 1, 1);
		addTag(262, 3, 1, 1);
		addTag(273, 4, 1, 288);
		addTag(277, 3, 1, 1);
		addTag(278, 4, 1, height);
		addTag(279, 4, 1, data.byteLength);
		addTag(284, 3, 1, 1);
		addTag(339, 3, 1, 3);
		addTag(33550, 12, 3, 184);
		addTag(33922, 12, 6, 208);
		addTag(34735, 3, 16, 256);
		view.setUint32(offset, 0, true);
		view.setFloat64(184, Math.abs(resolution[0]), true);
		view.setFloat64(192, Math.abs(resolution[1]), true);
		view.setFloat64(200, 0, true);
		view.setFloat64(208, 0, true);
		view.setFloat64(216, 0, true);
		view.setFloat64(224, 0, true);
		view.setFloat64(232, origin[0], true);
		view.setFloat64(240, origin[1], true);
		view.setFloat64(248, 0, true);
		const setKey = (addr, k1, k2, k3, k4) => {
			view.setUint16(addr, k1, true);
			view.setUint16(addr + 2, k2, true);
			view.setUint16(addr + 4, k3, true);
			view.setUint16(addr + 6, k4, true);
		};
		setKey(256, 1, 1, 0, 3);
		if (isProjected) {
			setKey(264, 1024, 0, 1, 1);
			setKey(272, 1025, 0, 1, 1);
			setKey(280, 3072, 0, 1, epsg);
		} else {
			setKey(264, 1024, 0, 1, 2);
			setKey(272, 1025, 0, 1, 1);
			setKey(280, 2048, 0, 1, epsg);
		}
		new Float32Array(buffer, 288).set(data);
		const blob = new Blob([buffer], { type: "image/tiff" });
		const url = URL.createObjectURL(blob);
		const a = document.createElement("a");
		a.href = url;
		a.download = filename;
		a.click();
		setTimeout(() => URL.revokeObjectURL(url), 2e3);
	} catch (error) {
		console.error("Erro ao gerar GeoTIFF:", error);
		alert("Erro ao exportar GeoTIFF. Verifique o console.");
	}
}
async function downloadUhiTiff(data, width, height, filename, origin, resolution, epsg, isProjected, mean = 0, stdDev = 1) {
	const uhiData = new Float32Array(data.length);
	for (let i = 0; i < data.length; i++) {
		const val = data[i];
		if (isNaN(val) || !isFinite(val) || val <= 0) uhiData[i] = 0;
		else if (val < mean) uhiData[i] = 1;
		else if (val < mean + .5 * stdDev) uhiData[i] = 2;
		else if (val < mean + 1.5 * stdDev) uhiData[i] = 3;
		else uhiData[i] = 4;
	}
	await downloadFloat32Tiff(uhiData, width, height, filename, origin, resolution, epsg, isProjected);
}
